class Solution {
    int n;
    vector<int> sequence;
    vector<bool> used;
    bool dfs(int index){
        while(index<(int)sequence.size()&&sequence[index])++index;
        if(index==(int)sequence.size())return true;
        for(int value=n;value>=1;--value){
            if(used[value])continue;
            int second=value==1?index:index+value;
            if(second>=(int)sequence.size()||sequence[second])continue;
            sequence[index]=sequence[second]=value;
            used[value]=true;
            if(dfs(index+1))return true;
            used[value]=false;
            sequence[index]=sequence[second]=0;
        }
        return false;
    }
    public:vector<int> constructDistancedSequence(int input){
        n=input;
        sequence.assign(2*n-1,0);
        used.assign(n+1,false);
        dfs(0);
        return sequence;
    }
};
